// `dotclaude-spec implement <package> [--note <text>] [--decision fix-code|revise-spec] [--json]`: starts or restarts a package.
// From `planned`, the change must be `planned` or `implementing`, each dep must be `done`, and no marker may be open.
// From `blocked`, a `--note` is needed. From `doing`, after a failed `verify` or a `reject`, a `--decision` is needed.
// The first `implement` of a package moves the change from `planned` to `implementing`.
// The move from `planned` records `sha` = `HEAD` on the event.

import { eventsOf } from "../domain/events.ts";
import { gateImplement } from "../domain/gates.ts";
import { hasTransition, PACKAGE_TRANSITIONS } from "../domain/states.ts";
import { parseArgs } from "./args.ts";
import { openMarkers } from "./files.ts";
import { head } from "./git.ts";
import type { Run } from "./run.ts";
import {
  changeState,
  evidence,
  isDecision,
  moveChange,
  movePackage,
  printMoved,
  stop,
  targetOf,
  usage,
} from "./transition.ts";

const USAGE =
  "Usage: dotclaude-spec implement <package> [--note <text>] [--decision fix-code|revise-spec] [--json]";

export const implementCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const parsed = parseArgs(args, { values: ["note", "decision"] });
  if (typeof parsed === "string") return usage(run, parsed);
  const [pkg, extra] = parsed.words;
  const { note, decision } = parsed.values;
  if (!pkg || extra !== undefined) return usage(run, USAGE);
  if (decision !== undefined && !isDecision(decision))
    return usage(run, "The decision is `fix-code` or `revise-spec`.");
  const target = await targetOf(run, pkg, "starts a package");
  if (target === null) return 1;
  const { id, events, states, state, file } = target;
  const step = { from: state, command: "implement", to: "doing" } as const;
  if (!hasTransition(PACKAGE_TRANSITIONS, step))
    return stop(
      run,
      `The package \`${pkg}\` is \`${state}\`, and \`implement\` cannot start it.`,
    );
  const change = changeState(events);
  const gate = gateImplement({
    from: state,
    change,
    depsDone: (file?.deps ?? []).every((dep) => states[dep] === "done"),
    openMarkers: await openMarkers(run.store, id),
    events: eventsOf(events, pkg),
    ...evidence({
      note,
      decision: isDecision(decision) ? decision : undefined,
    }),
  });
  if (!gate.ok) return stop(run, gate.reason);
  if (change === "planned") await moveChange(run, id, "implementing");
  const moved = await movePackage(
    run,
    id,
    pkg,
    "doing",
    evidence({
      note,
      decision: isDecision(decision) ? decision : undefined,
      sha: state === "planned" ? head(run.store.root) || undefined : undefined,
    }),
  );
  printMoved(run, "implement", moved, parsed.json);
  return 0;
};
